        def sim(a, b):
            h = 0
            row = 1
            while True:
                if row % 2 == 1:
                    if a >= row:
                        a -= row
                    else:
                        break
                else:
                    if b >= row:
                        b -= row
                    else:
                        break
                h += 1
                row += 1
            return h
        return max(sim(red, blue), sim(blue, red))

